deployment.program:
import credits.aleo;
import pwn_config_demo.aleo;
import pwn_hub_demo.aleo;

program pwn_elastic_proposal_demo.aleo;

struct Terms:
    credit_asset as address;
    collateral_asset as field;
    min_draw as u64;
    max_draw as u64;
    collateral_ratio as u64;
    repayment_ratio as u64;
    duration as u32;
    expiry as u32;
    lender_auth as field;

struct Authority:
    domain as u8;
    account as address;
    salt as field;

struct ModuleTag:
    module as address;
    tag as u8;

mapping terms_hash:
    key as field.public;
    value as field.public;

mapping available_credit:
    key as field.public;
    value as u64.public;

mapping repayments:
    key as field.public;
    value as u64.public;

mapping closed:
    key as field.public;
    value as boolean.public;

function draw:
    input r0 as field.public;
    input r1 as Terms.public;
    input r2 as u64.public;
    input r3 as address.private;
    assert.eq self.caller pwn_loan_demo.aleo;
    assert.eq r3 self.signer;
    gte r2 r1.min_draw into r4;
    lte r2 r1.max_draw into r5;
    and r4 r5 into r6;
    assert.eq r6 true;
    hash.bhp256 r1 into r7 as field;
    cast pwn_elastic_proposal_demo.aleo 2u8 into r8 as ModuleTag;
    hash.bhp256 r8 into r9 as field;
    call credits.aleo/transfer_public_to_private r3 r2 into r10 r11;
    async draw 4689983254106756858434100106993802722955720561375257438640100644187670946491field r9 r0 r7 r1 r2 r11 into r12;
    output r10 as credits.aleo/credits.record;
    output r12 as pwn_elastic_proposal_demo.aleo/draw.future;

finalize draw:
    input r0 as field.public;
    input r1 as field.public;
    input r2 as field.public;
    input r3 as field.public;
    input r4 as Terms.public;
    input r5 as u64.public;
    input r6 as credits.aleo/transfer_public_to_private.future;
    get.or_use pwn_hub_demo.aleo/approved[r0] false into r7;
    assert.eq r7 true;
    get.or_use pwn_hub_demo.aleo/approved[r1] false into r8;
    assert.eq r8 true;
    get terms_hash[r2] into r9;
    assert.eq r9 r3;
    get closed[r2] into r10;
    not r10 into r11;
    assert.eq r11 true;
    lt block.height r4.expiry into r12;
    assert.eq r12 true;
    get available_credit[r2] into r13;
    sub r13 r5 into r14;
    set r14 into available_credit[r2];
    await r6;

function receive_repayment:
    input r0 as field.public;
    input r1 as credits.aleo/credits.record;
    input r2 as u64.public;
    assert.eq self.caller pwn_loan_demo.aleo;
    call credits.aleo/transfer_private_to_public r1 pwn_elastic_proposal_demo.aleo r2 into r3 r4;
    async receive_repayment r0 r2 r4 into r5;
    output r3 as credits.aleo/credits.record;
    output r5 as pwn_elastic_proposal_demo.aleo/receive_repayment.future;

finalize receive_repayment:
    input r0 as field.public;
    input r1 as u64.public;
    input r2 as credits.aleo/transfer_private_to_public.future;
    get repayments[r0] into r3;
    add r3 r1 into r4;
    set r4 into repayments[r0];
    await r2;

function open_commitment:
    input r0 as field.public;
    input r1 as Terms.public;
    input r2 as credits.aleo/credits.record;
    input r3 as u64.public;
    input r4 as field.private;
    assert.eq r1.credit_asset credits.aleo;
    cast 1u8 self.signer r4 into r5 as Authority;
    hash.bhp256 r5 into r6 as field;
    assert.eq r1.lender_auth r6;
    gt r1.min_draw 0u64 into r7;
    gte r1.max_draw r1.min_draw into r8;
    and r7 r8 into r9;
    assert.eq r9 true;
    gte r3 r1.min_draw into r10;
    assert.eq r10 true;
    gt r1.collateral_ratio 0u64 into r11;
    gte r1.repayment_ratio 10000u64 into r12;
    and r11 r12 into r13;
    assert.eq r13 true;
    gt r1.duration 0u32 into r14;
    assert.eq r14 true;
    hash.bhp256 r1 into r15 as field;
    cast pwn_elastic_proposal_demo.aleo 2u8 into r16 as ModuleTag;
    hash.bhp256 r16 into r17 as field;
    call credits.aleo/transfer_private_to_public r2 pwn_elastic_proposal_demo.aleo r3 into r18 r19;
    async open_commitment r17 r0 r1 r15 r3 r19 into r20;
    output r18 as credits.aleo/credits.record;
    output r20 as pwn_elastic_proposal_demo.aleo/open_commitment.future;

finalize open_commitment:
    input r0 as field.public;
    input r1 as field.public;
    input r2 as Terms.public;
    input r3 as field.public;
    input r4 as u64.public;
    input r5 as credits.aleo/transfer_private_to_public.future;
    get.or_use pwn_hub_demo.aleo/approved[r0] false into r6;
    assert.eq r6 true;
    get pwn_config_demo.aleo/settings[true] into r7;
    assert.eq r7.protocol_fee_bps 0u16;
    contains terms_hash[r1] into r8;
    not r8 into r9;
    assert.eq r9 true;
    lt block.height r2.expiry into r10;
    assert.eq r10 true;
    set r3 into terms_hash[r1];
    set r4 into available_credit[r1];
    set 0u64 into repayments[r1];
    set false into closed[r1];
    await r5;

function cancel_commitment:
    input r0 as field.public;
    input r1 as Terms.public;
    input r2 as field.private;
    input r3 as u64.public;
    cast 1u8 self.signer r2 into r4 as Authority;
    hash.bhp256 r4 into r5 as field;
    assert.eq r1.lender_auth r5;
    hash.bhp256 r1 into r6 as field;
    call credits.aleo/transfer_public_to_private self.signer r3 into r7 r8;
    async cancel_commitment r0 r6 r3 r8 into r9;
    output r7 as credits.aleo/credits.record;
    output r9 as pwn_elastic_proposal_demo.aleo/cancel_commitment.future;

finalize cancel_commitment:
    input r0 as field.public;
    input r1 as field.public;
    input r2 as u64.public;
    input r3 as credits.aleo/transfer_public_to_private.future;
    get terms_hash[r0] into r4;
    assert.eq r4 r1;
    get closed[r0] into r5;
    not r5 into r6;
    assert.eq r6 true;
    get available_credit[r0] into r7;
    assert.eq r7 r2;
    set 0u64 into available_credit[r0];
    set true into closed[r0];
    await r3;

function withdraw_repayment:
    input r0 as field.public;
    input r1 as Terms.public;
    input r2 as field.private;
    input r3 as u64.public;
    gt r3 0u64 into r4;
    assert.eq r4 true;
    cast 1u8 self.signer r2 into r5 as Authority;
    hash.bhp256 r5 into r6 as field;
    assert.eq r1.lender_auth r6;
    hash.bhp256 r1 into r7 as field;
    call credits.aleo/transfer_public_to_private self.signer r3 into r8 r9;
    async withdraw_repayment r0 r7 r3 r9 into r10;
    output r8 as credits.aleo/credits.record;
    output r10 as pwn_elastic_proposal_demo.aleo/withdraw_repayment.future;

finalize withdraw_repayment:
    input r0 as field.public;
    input r1 as field.public;
    input r2 as u64.public;
    input r3 as credits.aleo/transfer_public_to_private.future;
    get terms_hash[r0] into r4;
    assert.eq r4 r1;
    get repayments[r0] into r5;
    sub r5 r2 into r6;
    set r6 into repayments[r0];
    await r3;

constructor:
    assert.eq edition 0u16;
